#!/usr/bin/env bash
# generate-check: gagal bila keluaran generator (swag -> docs/api, sqlc -> kode Go) yang ada di disk
# BASI terhadap sumbernya (docs/16 §2, docs/19 §3, ADR-0018).
#
# Cara kerja: ambil sidik jari (sha256) semua keluaran generator yang ada, jalankan `make generate`,
# ambil sidik jari lagi, bandingkan. Tidak bergantung pada status git, jadi aman dijalankan di
# pohon kerja yang kotor. Bila berbeda, keluaran terbaru DIBIARKAN di disk: tinggal di-commit.
set -euo pipefail
cd "$(dirname "$0")/.."

# Keluaran generator: seluruh docs/api, dan berkas Go berpenanda "Code generated by sqlc".
snapshot() {
  {
    find docs/api -type f 2>/dev/null || true
    grep -rl --include='*.go' '^// Code generated by sqlc' backend packages modules 2>/dev/null || true
  } | LC_ALL=C sort | xargs -r sha256sum
}

before="$(snapshot)"

log="$(mktemp)"
trap 'rm -f "$log"' EXIT
if ! make --no-print-directory generate >"$log" 2>&1; then
  echo "generate-check: 'make generate' gagal:" >&2
  cat "$log" >&2
  exit 1
fi

after="$(snapshot)"
if [ "$before" != "$after" ]; then
  echo "generate-check GAGAL: keluaran generator di disk basi terhadap sumbernya." >&2
  diff <(printf '%s\n' "$before") <(printf '%s\n' "$after") >&2 || true
  echo "File di atas sudah diperbarui oleh 'make generate'. Periksa 'git status', lalu commit hasilnya." >&2
  exit 1
fi
echo "generate-check OK: keluaran sqlc dan swag mutakhir."
